# -*- coding: utf-8 -*-
from __future__ import unicode_literals
import sys,json,hashlib
sys.path.insert(0,'D:\\Happy2018newの个人文件\\GitHub\\better-building-editor\\behavior_pack\\modern_projection')
def native(value):
    return value.encode('utf8') if bytes is str and isinstance(value, type('')) else value

def _native_tree(value):
    if isinstance(value, dict):
        return dict((_native_tree(key), _native_tree(item)) for key, item in value.items())
    if isinstance(value, tuple):
        return tuple(_native_tree(item) for item in value)
    if isinstance(value, list):
        return [_native_tree(item) for item in value]
    return native(value)

def _native_palette(data):
    """Convert SDK strings without copying the potentially large integer lists."""
    result = {}
    for key, value in data.items():
        if key in ('_native_render_profile', '_cauldron_profile', '_liquid_render_profile', '_spawner_profile', '_portal_profile'):
            continue
        if key in ('common', 'extra'):
            result[native(key)] = dict((_native_tree(material), indices)
                                       for material, indices in value.items())
        else:
            result[native(key)] = _native_tree(value)
    return result
from projection.model import Document
from projection.geometry_palette import prepare_palette
from projection import block_registry as registry
count=0; names=[]
for name in sorted(registry.BLOCKS):
 if not name.endswith('pressure_plate'):continue
 names.append(name)
 for aux in registry.aux_values(name):
  value=(name,aux); prepared=prepare_palette(Document((1,1,1),{(0,0,0):value}).palette_data())
  native_data=_native_palette(prepared); key=(native(name),aux)
  assert native_data[native('common')]=={key:[0]}
  assert native_data[native('states')][key]=={native('redstone_signal'):aux}
  assert type(next(iter(native_data[native('states')][key]))) is type(native('redstone_signal'))
  assert type(native_data[native('states')][key][native('redstone_signal')]) is int
  count+=1
print(json.dumps({'python':sys.version.split()[0],'names':names,'records':count,'native_signal_type':'int','stages':['Document.palette_data','prepare_palette','exact extracted _native_palette'],'passed':True}))

from projection.render_context import prepare_context_palette,prepare_document_context,prepare_context_batches
checks=0
for name in names:
 blocks={}
 signals=(0,1,7,15)
 for x,signal in zip((0,15,16,31),signals):
  blocks[(x,0,0)]=('minecraft:quartz_block',0)
  blocks[(x,1,0)]=(name,signal)
 doc=Document((32,2,1),blocks)
 source=doc.palette_data(); expected={(name,signal) for signal in signals}
 whole=prepare_context_palette(source,source)
 synchronous=prepare_document_context(doc,source)
 batches=prepare_context_batches(doc,source)
 variants=[('whole',whole),('incremental',synchronous)]+[('batch_'+str(index),row[2]) for index,row in enumerate(batches['_context_batches'])]
 observed={}
 for label,palette in variants:
  native_palette=_native_palette(palette)
  matched=set(value for value in palette['common'] if value[0]==name)
  if label.startswith('batch_'):
   observed.update((value,True) for value in matched)
  else:
   assert matched==expected,(name,label,matched)
  for value in matched:
   assert palette['states'][value]=={'redstone_signal':value[1]},(name,label,value)
   assert native_palette[native('states')][(native(name),value[1])]=={native('redstone_signal'):value[1]}
   checks+=1
 assert set(observed)==expected,(name,observed)
print(json.dumps({'python':sys.version.split()[0],'context_checks':checks,'names':len(names),'signals':[0,1,7,15],'positions':[0,15,16,31],'paths':['complete_palette_context','incremental_document_context','production_packed_batches'],'passed':True}))
